import type {NpcDefinition} from './npcDialogues';
import type {NpcLookOverride} from './beanLooks';
import type {PlayerProfile} from '../graphics/player';
import type {NpcPoseKind} from '../graphics/npcSeatPose';
export type {NpcPoseKind} from '../graphics/npcSeatPose';
/**
 * Townsfolk cast (Oct 12 2026, user-approved: "add about 60 townsfolk … what will they talk about? we need this to be more
 * diverse, but revolve around futbol still", then "mix up the current npcs with the stores too so it's more spread out").
 *
 *  - TOWNSFOLK_CAST: 60 new islanders. Island Square and the shop streets 15, the beaches 15, East Jetty and the Ferry Dock 10,
 *    Coral Cay 10, homes and parks 10. Nobody new on a pitch or in a match. They use the existing townsfolk runtime
 *    (lib/graphics/islandNpcs.ts): walking routes and pair chats, joggers (travel 'run'), and still poses built from the freestyle
 *    'sit' / 'lie' stances (lib/graphics/npcSeatPose.ts) for benches, towels and sunbathing. Far poses at 10 Hz, the off-screen
 *    10 Hz routine step and fishing focus mode (islandNpcs.setFocus) all apply to them because they are ordinary entries.
 *  - TOWNSFOLK_VOICES: a persona and extra conversation openers for every existing islander. The greeting stays the first
 *    opener (lib/town/npcOpeners.ts), so wording that gameplay relies on is unchanged; topics are untouched.
 *  - TOWNSFOLK_MOVES: six movable regulars (no job, quest, onboarding, café route, freestyle or work prop tie) spread away from
 *    the Island Square spawn and the busiest clusters, so every area mixes old and new faces.
 *
 * Every fact is listed with its source in docs/npc-cast.md. Rules for the lines: football at the centre; kid-friendly, short
 * (1–2 sentences, ages 7–12); no betting, alcohol, brands, politics or rivalry put-downs; real people only with well-documented
 * public facts and never with invented quotes. The rig has no headscarf, glasses, wheelchair or dog asset, so none is faked:
 * para football appears through the people who play, coach and guide it, in their own words.
 */
export type NpcAge='kid'|'teen'|'adult'|'elder';
export type TownArea='square'|'beach'|'pier'|'cay'|'residential';
const base:PlayerProfile={height:1,build:1,legs:1,stride:1,cadence:1,lean:1,armSwing:1,agility:1,weight:1,crouch:1};
/** Rig height profiles (player.setProfile): children are clearly smaller, teens a little; grandparents walk a touch slower. */
export const AGE_PROFILES:Record<Exclude<NpcAge,'adult'>,PlayerProfile>={
 kid:{...base,height:.74,build:.92,stride:.9,cadence:1.12,armSwing:1.1,agility:1.15,weight:.85},
 teen:{...base,height:.88,build:.95,stride:.98,cadence:1.05,agility:1.08,weight:.92},
 elder:{...base,height:.97,build:1.02,legs:.98,stride:.9,cadence:.92,lean:.9,armSwing:.85,agility:.9,weight:1.05},
};
/** `?npcmore=0` keeps today's cast and places (heat A/B only). Server render and tests always see the full cast. */
export const townsfolkCastEnabled=()=>typeof window==='undefined'||!/[?&]npcmore=0(&|$)/.test(window.location.search);

type Who={ch:'female'|'male';skin:number;clothing:'classic'|'coast'|'sunset';age:NpcAge;body?:'balanced'|'strong'|'slim';look?:NpcLookOverride};
type How={pose?:NpcPoseKind;yaw?:number;travel?:'run'};
type Talk=[question:string,answer:string,followQuestion:string,followAnswer:string];
const face=(skin:number)=>skin<=2?'light' as const:skin<=4?'warm' as const:'deep' as const;
function folk(area:TownArea,id:string,name:string,role:string,pursuit:string,x:number,z:number,who:Who,how:How,persona:string,greeting:string,lines:string[],talk:Talk):NpcDefinition{
 return {id:`folk-${id}`,name,role,pursuit,x,z,area,character:who.ch,face:face(who.skin),clothing:who.clothing,body:who.body??'balanced',age:who.age,
  look:{skin:who.skin,...who.look},pose:how.pose,workYaw:how.yaw,travel:how.travel,persona,greeting,lines,
  topics:[{id:'chat',question:talk[0],answer:talk[1],followUp:{question:talk[2],answer:talk[3]}}]};
}
const GREY='#c9c6c0',WHITE='#ece9e2',SILVER='#a9a7a3';
// North Beach towels (lib/town/shoreline.ts NORTH_BEACH_UMBRELLAS, world.ts): each towel sits at umbrella + (3, 1), turned 0.15·i.
const towel=(i:number,[x,z]:[number,number])=>({x:x+3,z:z+1,yaw:.15*i});
const T1=towel(1,[-15,-224]),T2=towel(2,[22,-229]),T3=towel(3,[62,-229]),T4=towel(4,[105,-227]);

