 'scooter-eli':{persona:'A neighbourhood cruiser who now rides the quiet library street.',lines:['The library street is quiet and smooth. Great for scooting!','I scoot to the Junior Club to watch the little ones train.']},
 'video-celeste':{persona:'A scanning guide who uses clips to show where players look.',lines:['Pause a clip just before a pass. Where is the receiver looking?','Scanning means looking away from the ball, then back again.']},
 'video-idriss':{persona:'A support guide who studies how players offer help.',lines:['Support means being where your teammate can see you.','A good support angle is to the side, not hiding behind a defender.']},
